import json
# Fill the 28x28 masked lattice: outer field=1, frame=4, interior follows the
# diagonal five-color cycle, while all original nonzero seed exceptions persist.
grid=[]
for r in range(28):
    row=[]
    for c in range(28):
        if r < 2:
            v=1
        elif r == 2:
            v=1 if c < 2 else 4
        elif c < 2:
            v=1
        elif c == 2:
            v=4
        else:
            v=[1,3,5,7,9][(r+c)%5]
        row.append(v)
# Preserve the observed non-periodic seed entries (the demos preserve existing ink).
for r,c,v in [(3,4,2),(3,5,1),(4,3,2),(5,3,1)]:
    grid[r][c]=v
assert len(grid)==28 and all(len(row)==28 for row in grid)
assert set(sum(grid,[])) <= set(range(10))
print(json.dumps({'action':'submit','grid':grid},separators=(',',':')))
